def check(pars, dep, k):
	_oper = 0
	depths = [1 for i in range(len(pars))]
	for i in range(len(pars) - 1, 0, -1):
		if depths[i] == dep and pars[i] != 0:
			_oper += 1
		else:
			par = pars[i]
			depths[par] = max(depths[par], depths[i] + 1)
	return _oper <= k
t = int(input())
for _ in range(t):
	(n, k) = input().split()
	(n, k) = (int(n), int(k))
	pars = [0]
	pars_temp = input().split()
	pars += [int(i) - 1 for i in pars_temp]
	(low, high) = (1, n - 1)
	while low < high:
		mid = (low + high) // 2
		if check(pars, mid, k):
			high = mid - 1
		else:
			low = mid + 1
	if high >= 1 and check(pars, high, k):
		print(high)
	else:
		print(high + 1)
